-- Venue Live Guest "Wedding Adat Sunda". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara sunda), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'sunda', 'Wedding Adat Sunda', 'sunda', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 140, 'center 38%',
  $t${"name":"Adat Sunda","orn":"diamond","ui":{"ivory":"#FBF5E8","white":"#FFFFFF","soft":"#EADBBE","soft2":"#C9A24A","accent":"#8B5A2B","deep":"#3B2414","ink":"#3B2414","mute":"#8A6A4A","line":"#E8D8B8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F8EFDC","ink":"#3B2414","accent":"#8B5A2B","gold":"#C9A24A","leaf":"#EADBBE","hbg":"rgba(251,245,232,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(59,36,20,.9)","acc":"#E8C873","on":"#3B2414"},"scr":{"wine":"#3B2414","veil":"251,245,232"}}$t$::jsonb
